import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from c_adv_common import ROOT,OUT,GROUPS

def publish(out,dest,x,c):
 ppt=OUT/'ppt/advanced'/out.name; ppt.mkdir(parents=True,exist_ok=True)
 w=pd.read_csv(out/'warmth_window_summary.csv'); fig,ax=plt.subplots(figsize=(16,9),layout='constrained'); ax.plot(w.year,w.warmth_30,label='30°',color='#222222',lw=3); ax.plot(w.year,w.warmth_15,'--',label='15°'); ax.plot(w.year,w.warmth_45,'--',label='45°'); ax.fill_between(w.year,0,w.warmth_30,where=w.warmth_30>=0,color='#ef9b48',alpha=.3); ax.fill_between(w.year,0,w.warmth_30,where=w.warmth_30<0,color='#36aab6',alpha=.3); ax.axhline(0,color='gray',lw=.7); ax.set(title='Five-year mean hue projection, by release year',xlabel='Release year',ylabel='Cosine hue projection'); ax.legend(); fig.savefig(ppt/'warmth_trend.png',dpi=150); plt.close(fig)
 s=pd.read_csv(out/'convergence_summary.csv'); s=s[s.feature_set=='base'].set_index('period').loc[['2001-2010','2011-2020','2021-2025']]; fig,ax=plt.subplots(figsize=(16,9),layout='constrained'); xx=np.arange(3); ax.errorbar(xx,s.global_heterogeneity_index,yerr=[s.global_heterogeneity_index-s.ci_low,s.ci_high-s.global_heterogeneity_index],fmt='o-',capsize=6,lw=3); ax.set_xticks(xx,s.index); ax.set(title='Mean pairwise heterogeneity across seven groups',ylabel='Bias-corrected squared distance'); fig.savefig(ppt/'convergence.png',dpi=150); plt.close(fig)
 # Every registered entry identifies its producing stage and the fixed reference policy.
 by_name={'relations.csv':('c06_relations.py','movies.csv; color_features.csv; country_group.csv','19694','movie_equal','HSV / D65 Lab','none'),'cooccurrence.csv':('c06_relations.py','relations.csv','per group: n_valid_movies','movie_equal / group_equal','joint probability','none'),'spatial_features.csv':('c07_spatial.py','data/posters; movies.csv','19694 rows; see image_audit.csv','movie_equal','HSV / D65 Lab','none'),'group_summary.csv':('c08_distributions.py','relations.csv; spatial_features.csv','per row: n_valid','movie_equal','original units','pointwise bootstrap 95% CI'),'advanced_contrasts.csv':('c08_distributions.py','relations.csv; spatial_features.csv','per row: n_a and n_b','movie_equal / group_equal','original units','pointwise bootstrap 95% CI'),'pca_scores.csv':('c09_synthesis.py','relations.csv; spatial_features.csv','per model: scaler.json n','time_movie_equal / country_group_equal','weighted standardized PCA','none'),'convergence_summary.csv':('c09_synthesis.py','relations.csv; spatial_features.csv','per period: period_support.csv','country_group_equal','bias-corrected squared distance','joint bootstrap pointwise 95% CI')}
 fig_sources={'fig_q2_cooccurrence_joint.png':'cooccurrence.csv','fig_q4_cooccurrence_joint.png':'cooccurrence.csv','fig_q2_relations.png':'cooccurrence.csv; relations.csv','fig_q4_relations.png':'cooccurrence.csv; cooccurrence_reference.csv; relations.csv','fig_q2_spatial.png':'spatial_maps.npz; spatial_features.csv','fig_q4_spatial.png':'spatial_maps.npz; spatial_map_residuals.npz; spatial_features.csv','fig_q2_distributions.png':'group_summary.csv; tail_shares.csv; relations.csv; spatial_features.csv','fig_q4_distributions.png':'group_summary.csv; tail_shares.csv; relations.csv; spatial_features.csv','fig_q2_fingerprint.png':'profiles.csv; pca_scores.csv; pca_variance.csv','fig_q4_fingerprint.png':'profiles.csv; pca_scores.csv; pca_variance.csv','fig_q4_convergence.png':'pairwise_period_distance.csv; convergence_summary.csv; convergence_bootstrap.csv; period_support.csv','fig_q4_convergence_extended.png':'pairwise_period_distance.csv; convergence_summary.csv; convergence_bootstrap.csv; period_support.csv','fig_q2_q4_warmth.png':'relations.csv; spatial_features.csv; lab_mean_bootstrap.csv','fig_spot_check_cards.png':'spot_check_selection.csv; relations.csv; spatial_features.csv; selected posters','fig_q2_q4_contrasts_forest.png':'advanced_contrasts.csv; standardization_reference.csv'}
 rows=[]
 for path in sorted(out.rglob('*')):
  if not path.is_file() or path.name=='artifact_index.csv': continue
  default=('c_adv_plot.py' if path.name.startswith(('spot_check','spatial_map_residual','forest_plot','cooccurrence_top','warmth_window','lab_ellipse','spatial_centroids')) else 'c08_distributions.py / c09_synthesis.py','see manifest.json and generation scripts','see corresponding coverage / support table','time_movie_equal / country_group_equal','see column names and config','see corresponding CI fields')
  stage,inputs,n,reference,scale,ci=by_name.get(path.name,default)
  if path.name.startswith(('cooccurrence_reference','missing_features','missing_details','orphan_features','genre_membership')): stage,inputs='c06_relations.py','movies.csv; color_features.csv; movie_details.csv; country_group.csv'
  elif path.name.startswith(('spatial_maps','image_audit')): stage,inputs='c07_spatial.py','data/posters; movies.csv; country_group.csv'
  elif path.name.startswith(('tail_','coverage','standardization_reference','country_reference_weights','lab_mean_bootstrap','country_deviation_bootstrap')): stage,inputs='c08_distributions.py','relations.csv; spatial_features.csv'
  elif path.name.startswith(('pca_','scaler','profiles','correlations','period_support','pairwise_period','convergence_bootstrap','cluster_stability','genre_common','genre_adjusted')): stage,inputs='c09_synthesis.py','relations.csv; spatial_features.csv; genre_membership.csv'
  elif path.name=='legacy_validation_log.txt': stage,inputs='c_legacy_check.py','original inputs and legacy scripts'
  elif path.name=='reproducibility_log.txt': stage,inputs='c_adv_reproducibility.py','group statistics and synthesis results'
  elif path.name in ('visual_review.md','spot_check_audit.csv','analysis_notes.md'): stage,inputs='manual_review','generated figures and corresponding source tables'
  elif path.name=='validation_report.md': stage,inputs='c99_validate.py','analysis outputs and verification records'
  elif path.name=='synthetic_test_log.txt': stage,inputs='test_advanced_synthetic.py','synthetic colors and images'
  if path.parent.name=='smoke': stage='c07_spatial.py'
  rows.append(dict(path=str(path.relative_to(ROOT)).replace('\\','/'),generating_script=stage,input_tables=inputs,n_valid=n,reference_sample=reference,scale=scale,interval_meaning=ci,command=(f'python outputs/c/scripts/c07_spatial.py --run-id {out.name} --mode smoke --limit 100' if path.parent.name=='smoke' else 'manual review' if stage=='manual_review' else f'python outputs/c/scripts/c07_spatial.py --run-id {out.name} --mode full --resume' if stage=='c07_spatial.py' else f'python outputs/c/scripts/c99_validate.py --stage advanced --run-id {out.name}' if stage=='c99_validate.py' else f'python outputs/c/scripts/{stage.split(" / ")[0]} --run-id {out.name}')))
 for path in sorted(dest.glob('*.png')):
  rows.append(dict(path=str(path.relative_to(ROOT)).replace('\\','/'),generating_script='c_adv_plot.py',input_tables=fig_sources.get(path.name,'see named statistical table'),n_valid='see input tables and figure labels',reference_sample='time_movie_equal / country_group_equal',scale='see figure axes',interval_meaning='pointwise 95% where shown; see figure',command=f'python outputs/c/scripts/c_adv_plot.py --run-id {out.name} --figures all'))
 for path in sorted(ppt.glob('*.png')):
  rows.append(dict(path=str(path.relative_to(ROOT)).replace('\\','/'),generating_script='c_adv_plot.py',input_tables='warmth_window_summary.csv' if path.name=='warmth_trend.png' else 'convergence_summary.csv',n_valid='see source table',reference_sample='time_movie_equal' if path.name=='warmth_trend.png' else 'country_group_equal',scale='see figure axes',interval_meaning='pointwise 95% for convergence',command=f'python outputs/c/scripts/c_adv_plot.py --run-id {out.name} --figures all'))
 rows.append(dict(path=str((out/'artifact_index.csv').relative_to(ROOT)).replace('\\','/'),generating_script='c_adv_plot.py',input_tables='completed run outputs',n_valid='see listed artifacts',reference_sample='see listed artifacts',scale='see listed artifacts',interval_meaning='see listed artifacts',command=f'python outputs/c/scripts/c_adv_plot.py --run-id {out.name} --figures all'))
 pd.DataFrame(rows).to_csv(out/'artifact_index.csv',index=False)
